S = 3*sin(2*pi*150*t);

NFFT = 2^nextpow2(L);
NFFT1 = L;
NFFT2 = NFFT/2;
NFFT3 = NFFT/4;

Y = fft(S, NFFT1)/NFFT1;
Y2 = fft(S, NFFT2)/NFFT2;
Y3 = fft(S, NFFT3)/NFFT3;

EY = sum(Y.*conj(Y));
